use super::*;
fn scalar_canonical(mut atoms:Vec<u64>,mut values:Vec<u64>)->Truth{
 let mut j=0;while j<atoms.len(){let bit=1usize<<j;let essential=(0..values.len()).any(|r|r&bit==0&&values[r]!=values[r|bit]);if essential{j+=1;}else{values=(0..values.len()/2).map(|r|values[(r&(bit-1))|((r&!(bit-1))<<1)]).collect();atoms.remove(j);}}let mut table=Table::low(0);for(i,v)in values.into_iter().enumerate(){table.set(i,v);}Truth{atoms,table}
}
#[test]fn every_one_hot_basis_proves_insert_remove_and_essential_maps_through_fourteen_variables(){
 for n in 0..=SUPPORT_CAP{for row in 0..1usize<<n{let mut t=Table::low(0);t.set(row,1);if n<SUPPORT_CAP{for j in 0..=n{let v=t.insert(j,n);let lo=(row&((1usize<<j)-1))|((row>>j)<<(j+1));let mut expected=Table::low(0);expected.set(lo,1);expected.set(lo|(1usize<<j),1);assert_eq!(v,expected,"insert n{n} row{row} j{j}");assert!(!v.essential(j,n+1));assert_eq!(v.remove(j,n+1),t);}}
  for j in 0..n{assert!(t.essential(j,n));let mut expected=Table::low(0);if row>>j&1==0{let at=(row&((1usize<<j)-1))|((row>>(j+1))<<j);expected.set(at,1);}assert_eq!(t.remove(j,n),expected,"remove n{n} row{row} j{j}");}
 }}
}
#[test]fn canonical_lifting_and_boolean_products_match_independent_scalar_truths(){
 use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};let mut h=Shake256::default();h.update(b"truth14-independent-scalar-reference-v1");let mut rng=h.finalize_xof();
 for n in 0..=SUPPORT_CAP{for pattern in 0..16{let mut bytes=vec![0u8;1usize<<n];rng.read(&mut bytes);let values:Vec<_>=(0..1usize<<n).map(|r|match pattern%4{0=>(bytes[r]&1)as u64,1=>(r.count_ones()%2)as u64,2=>u64::from((r&0x2222).count_ones()%2==1),_=>u64::from(pattern&4!=0)}).collect();let mut table=Table::low(0);for(i,&v)in values.iter().enumerate(){table.set(i,v);}let atoms:Vec<_>=(0..n as u64).collect();assert_eq!(Truth::canonical(atoms.clone(),table),scalar_canonical(atoms,values));}
  for repeat in 0..16{let a_ids:Vec<_>=(0..n as u64).filter(|i|(i+repeat)%3!=0).collect();let b_ids:Vec<_>=(0..n as u64).filter(|i|(i+repeat)%3!=1).collect();let mut make=|ids:Vec<u64>|{let mut bytes=vec![0u8;1usize<<ids.len()];rng.read(&mut bytes);let mut table=Table::low(0);for(i,b)in bytes.into_iter().enumerate(){table.set(i,(b&1)as u64);}Truth::canonical(ids,table)};let a=make(a_ids);let b=make(b_ids);let mut s=Support{qubits:vec![],bits:vec![],base_condition:Truth::constant(true),condition_stack:vec![],next_atom:100};let and=s.and(&a,&b);let xor=s.xor(&a,&b);let eval=|f:&Truth,r:usize|{let p:Vec<_>=f.atoms.iter().map(|&v|v as usize).collect();f.value_in_union(&p,r)};for row in 0..1usize<<n{assert_eq!(eval(&and,row),eval(&a,row)&eval(&b,row));assert_eq!(eval(&xor,row),eval(&a,row)^eval(&b,row));}}
 }
}
#[test]fn rewritten_random_guarded_measurement_circuits_preserve_full_values_and_phase(){
 use crate::circuit::{BitId,QubitId,RegisterId};use crate::sim::Simulator;use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};struct Words(Vec<u8>,usize);impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.0[self.1..self.1+b.len()]);self.1+=b.len();}}
 let mut h=Shake256::default();h.update(b"truth14-random-circuits-v1");let mut rng=h.finalize_xof();let mut next=||{let mut b=[0u8;8];rng.read(&mut b);u64::from_le_bytes(b)};
 for circuit in 0..48{let mut ops=Vec::new();for q in 0..8{let mut o=Op::empty();o.kind=OperationType::AppendToRegister;o.q_target=QubitId(q);o.r_target=RegisterId(0);ops.push(o);}for b in 0..2{let mut o=Op::empty();o.kind=OperationType::AppendToRegister;o.c_target=BitId(b);o.r_target=RegisterId(1);ops.push(o);}let mut depth=0;
  for _ in 0..240{let v=next();let mut o=Op::empty();let q=v%12;let q2=(q+1+(v>>8)%11)%12;let mut q3=(q2+1+(v>>16)%11)%12;if q3==q{q3=(q3+1)%12;if q3==q2{q3=(q3+1)%12;}}match v%13{0 if depth<3=>{o.kind=OperationType::PushCondition;o.c_condition=BitId((v>>24)%8);depth+=1;},1 if depth>0=>{o.kind=OperationType::PopCondition;depth-=1;},2=>{o.kind=OperationType::Hmr;o.q_target=QubitId(q);o.c_target=BitId((v>>24)%8);},3=>{o.kind=OperationType::R;o.q_target=QubitId(q);},4=>{o.kind=OperationType::BitInvert;o.c_target=BitId((v>>24)%8);},5=>{o.kind=if v&0x100000!=0{OperationType::BitStore0}else{OperationType::BitStore1};o.c_target=BitId((v>>24)%8);},6=>{o.kind=OperationType::X;o.q_target=QubitId(q);},7=>{o.kind=OperationType::CZ;o.q_control1=QubitId(q);o.q_target=QubitId(q2);},8=>{o.kind=OperationType::Z;o.q_target=QubitId(q);},9=>{o.kind=OperationType::Swap;o.q_control1=QubitId(q);o.q_target=QubitId(q2);},_=>{o.kind=OperationType::CCX;o.q_control1=QubitId(q);o.q_control2=QubitId(q2);o.q_target=QubitId(q3);}}o.validate();ops.push(o);}
  for _ in 0..depth{let mut o=Op::empty();o.kind=OperationType::PopCondition;ops.push(o);}let out=simplify_classical(simplify_products(ops.clone()));let nd=ops.iter().filter(|o|matches!(o.kind,OperationType::Hmr|OperationType::R)).count();assert_eq!(nd,out.iter().filter(|o|matches!(o.kind,OperationType::Hmr|OperationType::R)).count());
  for batch in 0..16{let mut bytes=vec![0u8;nd*8];for b in &mut bytes{*b=next()as u8;}let mut ra=Words(bytes.clone(),0);let mut rb=Words(bytes,0);let mut a=Simulator::new(12,8,&mut ra);let mut b=Simulator::new(12,8,&mut rb);for lane in 0..64{let v=batch*64+lane;for q in 0..8{a.qubits[q]|=((v>>q&1)as u64)<<lane;}a.bits[0]|=((v>>8&1)as u64)<<lane;a.bits[1]|=((v>>9&1)as u64)<<lane;}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits,"circuit{circuit} batch{batch}");assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);assert!(b.stats.toffoli_gates<=a.stats.toffoli_gates);}
 }
}
